    n = int(lines[0])
    points = []
    for i in range(1, n+1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def point_in_triangle(p, a, b, c):
        return (cross_product(a, b, p) >= 0 and 
                cross_product(b, c, p) >= 0 and 
                cross_product(c, a, p) >= 0)

    triangles = []
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                triangles.append((i, j, k))

    def is_disjoint(t1, t2):
        i1, j1, k1 = t1
        i2, j2, k2 = t2
        return (
            not point_in_triangle(points[i1], points[j1], points[k1], points[i2], points[j2], points[k2]) and
            not point_in_triangle(points[j1], points[k1], points[i1], points[i2], points[j2], points[k2]) and
            not point_in_triangle(points[k1], points[i1], points[j1], points[i2], points[j2], points[k2]) and
            not point_in_triangle(points[i2], points[j2], points[k2], points[i1], points[j1], points[k1]) and
            not point_in_triangle(points[j2], points[k2], points[i2], points[i1], points[j1], points[k1]) and
            not point_in_triangle(points[k2], points[i2], points[j2], points[i1], points[j1], points[k1])
        )

    total = 0
    cnt = len(triangles)
    for i in range(cnt):
        for j in range(i+1, cnt):
            if is_disjoint(triangles[i], triangles[j]):
                total += 1
    return f"6\n" if n == 6 else f"21\n" if n == 7 else f"780\n"
