def solution(input_str):
    n = int(input_str.split('\n')[0])
    s = []
    r = []
    for i in range(n):
        s_part, r_part = input_str.split('\n')[i+1].split()
        s.append(int(s_part))
        r.append(int(r_part))

    result = []
    for i in range(n):
        winner = True
        for j in range(n):
            if s[i] == s[j]:
                if r[i] < r[j]:
                    winner = False
                    break
                continue

            if r[i] == r[j]:
                if s[i] < s[j]:
                    winner = False
                    break
                continue

            # Check if we can pick S, R > 0 such that T_i <= T_j
            # S/a_i + R/b_i <= S/a_j + R/b_j
            # S(1/a_i - 1/a_j) <= R(1/b_i - 1/b_j)
            # S(1/s_i - 1/s_j) <= R(1/r_i - 1/r_j)

            lhs_coef = 1.0 / s[i] - 1.0 / s[j]
            rhs_coef = 1.0 / r[i] - 1.0 / r[j]

            if lhs_coef == 0:
                if rhs_coef < 0:
                    winner = False
                    break
            elif rhs_coef == 0:
                if lhs_coef < 0:
                    winner = False
                    break
            else:
                # Both non-zero
                if lhs_coef / rhs_coef < 0:
                    winner = False
                    break
        if winner:
            result.append(i + 1)

    return ' '.join(map(str, result)) + '\n'
