                in_degree[v] += 1

    queue = [i for i in range(2, adj_size) if in_degree[i] == 1]
    while queue:
        u = queue.pop(0)
        in_degree[u] = -1
        for v in adj[u]:
            if in_degree[v] >= 0:
                in_degree[v] -= 1
                if in_degree[v] == 1:
