    if cycle_len >= threshold:
        # Build cycle
        path = [target]
        return f"1\n{' '.join(map(str, sorted([n for n in range(n + 1)] if n > 0))[:k])}"

    # Output independent set
    visited = [False] * (n + 1)
    ind_set = []

    def build_independent():
        visited_set = set()
        queue_indep = []

        def get_ind(u):
            if u in visited_set:
                return set()
            visited_set.add(u)
