    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    from collections import deque

    def dfs(current, path, visited_state):
        if len(current) == 1:
            if current[0] == 1:
                return "\n".join(path)
            return None

        visited_set = visited_state

        for i in range(len(current)):
            for j in range(i + 1, len(current)):
                x, y = current[i], current[j]
                new_val = f(x + y)
                next_list = current[:i] + current[i+1:j] + [new_val, current[j]]

                if len(current) == 2:
                    next_list = [x, y]
                    if f(x + y) == 1:
                        return f"{x} {y}"

                key = tuple(sorted(next_list))
                if key not in visited_set:
                    if dfs(next_list, path + [f"{x} {y}"], visited_set | {key}):
                        return f"{x} {y}"

                new_list = current[:i] + current[j+1:] + [new_val]
                key = tuple(sorted(new_list))
                if key not in visited_set:
                    dfs(new_list, path + [f"{x} {y}"], visited_set | {key})

    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            if n > 2:
                result = dfs([a[i], a[j], *a[:i] + a[i+1:j] + a[j+1:], ()])
                if result:
                    return f"YES\n{result}"

    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            x, y = a[i], a[j]
            new_val = f(x + y)
            result = dfs([x, y, new_val], [f"{x} {y}"], {tuple(sorted([x, y, new_val]))})
            if result:
                return f"YES\n{result}\n{result}"

    return "NO"
