def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, k = map(int, lines[0].split())

    if n == 1:
        return "0\n"

    edges = []
    adj = defaultdict(list)

    for i in range(1, n):
        line_idx = lines[i]
        u, v = map(int, line_idx.split())
        edges.append((u, v))
